-- МИР follows the section on every path (src/signup/mir-from-section.ts).
-- Also applied by the app bootstrap (db-core.ts). Idempotent (IF NOT EXISTS). Writes no data by itself.

CREATE TRIGGER IF NOT EXISTS trg_signups_mir_from_section_insert
AFTER INSERT ON signups
WHEN TRIM(COALESCE(NEW.mir_code, '')) = '' AND (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END) != ''
BEGIN
  INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
  SELECT lower(hex(randomblob(16))), NEW.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF('', ''), '—'), (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
  WHERE '' != (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END);
  UPDATE signups SET mir_code = (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END) WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_signups_mir_from_section_update
AFTER UPDATE OF draft_section, published_section, mir_code ON signups
WHEN TRIM(COALESCE(NEW.mir_code, '')) = '' AND (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END) != ''
BEGIN
  INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
  SELECT lower(hex(randomblob(16))), NEW.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF(COALESCE(OLD.mir_code, ''), ''), '—'), (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
  WHERE COALESCE(OLD.mir_code, '') != (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END);
  UPDATE signups SET mir_code = (CASE WHEN TRIM(COALESCE(NEW.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.draft_section, '')), 1, 2) ELSE '' END) END) WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_partner_people_mir_from_section_insert
AFTER INSERT ON partner_people
WHEN NEW.designation_number IS NULL AND NEW.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), '') != '' AND COALESCE(NEW.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), '')
BEGIN
  INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
  VALUES (lower(hex(randomblob(16))), NEW.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF(COALESCE(NEW.designation_mir, ''), ''), '—'), COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), ''), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
  UPDATE partner_people SET designation_mir = COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '') WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_partner_people_mir_from_section_update
AFTER UPDATE OF section_draft, section_published, covered_by_signup_id, withdrawn_at ON partner_people
WHEN NEW.designation_number IS NULL AND NEW.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), '') != '' AND COALESCE(NEW.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), '')
BEGIN
  INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
  VALUES (lower(hex(randomblob(16))), NEW.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF(COALESCE(NEW.designation_mir, ''), ''), '—'), COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(NEW.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(NEW.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(NEW.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(NEW.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = NEW.covered_by_signup_id), ''), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
  UPDATE partner_people SET designation_mir = COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '') WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_signups_mir_to_covered_partners
AFTER UPDATE OF draft_section, published_section, designation_mir, designation_number ON signups
WHEN EXISTS (SELECT 1 FROM partner_people p WHERE p.covered_by_signup_id = NEW.id AND p.designation_number IS NULL AND p.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), '') != '' AND COALESCE(p.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), ''))
BEGIN
  INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
  SELECT lower(hex(randomblob(16))), p.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF(COALESCE(p.designation_mir, ''), ''), '—'), COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), ''), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
  FROM partner_people p WHERE p.covered_by_signup_id = NEW.id AND p.designation_number IS NULL AND p.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), '') != '' AND COALESCE(p.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), '');
  UPDATE partner_people SET designation_mir = COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '')
  WHERE covered_by_signup_id = NEW.id AND partner_people.designation_number IS NULL AND partner_people.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '') != '' AND COALESCE(partner_people.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '');
END;
